/// `xs`, each once, in the order of its last.
pub fn distinct(mut xs: Strings) -> Strings {
    loop {
        if null_p(xs) {
            return nil::<Str>();
        } else if string_member_p(car(xs), cdr(xs)) {
            xs = cdr(xs);
            continue;
        } else {
            return kayak_rt::heap_cons(car(xs), distinct(cdr(xs)));
        }
    }
}

