pub fn list_ref_i64(mut ts: Tys, mut i: i64) -> &'static Ty {
    loop {
        if i64_eq(i, 0i64) {
            return car(ts);
        } else {
            (ts, i) = (cdr(ts), i64_minus(i, 1i64));
            continue;
        }
    }
}

