/// Of the facts `fs`, each that begins `prefix`, the rest: one pass,
/// making a pair only for each found.
pub fn facts_after(mut fs: Facts, mut prefix: Str) -> Strings {
    loop {
        if null_p(fs) {
            return nil::<Str>();
        } else if {
            let tagcase_ = car(fs);
            match *tagcase_ {
                Fact::Fact(ff, fp, what) => {
                    has_prefix_p(what, prefix)
                }
            }
        } {
            return kayak_rt::heap_cons({
                let tagcase_ = car(fs);
                match *tagcase_ {
                    Fact::Fact(ff, fp, what) => {
                        after_prefix(what, prefix)
                    }
                }
            }, facts_after(cdr(fs), prefix));
        } else {
            fs = cdr(fs);
            continue;
        }
    }
}

/// Whether a procedure is given a place, `(place p)` (C34): only then has
/// it `place-needs` or `region-within` facts to look for.
pub fn given_place_p(sc: &'static Scheme) -> bool {
    let tagcase_ = sc;
    match *tagcase_ {
        Scheme::Scheme(tvars, t) => {
            let tagcase_ = t;
            match *tagcase_ {
                Ty::TyProc(es, ps, r) => {
                    any_p(lambda1(move |p: &'static Ty| {
                        let tagcase_ = p;
                        match *tagcase_ {
                            Ty::TyData(d, args) => {
                                string_eq_p(d, str_lit("%place"))
                            }
                            _ => {
                                let other = tagcase_;
                                false
                            }
                        }
                    }), ps)
                }
                _ => {
                    let other = tagcase_;
                    false
                }
            }
        }
    }
}

/// A definition's facts, those of types settled: `%metas what ?k ...`
/// is `what T ...`.
pub fn settle_facts(s: &'static St) -> Facts {
    map(lambda1(move |f: &'static Fact| {
        let tagcase_ = f;
        match *tagcase_ {
            Fact::Fact(file, pos, what) => {
                if has_prefix_p(what, str_lit("%metas ")) {
                    let ws = read_all(string_chars(after_prefix(what, str_lit("%metas "))), str_lit(""), 1i64);
                    fact(file, pos, string_append(sym_name(car(ws)), string_append(str_lit(" "), words_of(map(lambda1(move |m: &'static Sexp| {
                        show_sexp(settled_sexp(s, ty_meta(meta_number(sym_name(m))), false))
                    }), cdr(ws))))))
                } else {
                    f
                }
            }
        }
    }), st_facts(s))
}

