/// `(proj f a ...)`: the poly procedure `f` at the arguments given for
/// its binders in order, types and regions (places too), as FX-26
/// projects one; in Rust `f`, whose generics the call finds. A proj of
/// a proj (C60): FX-26's nested `poly`s have their binders in the order
/// KFX's one has them, so the arguments are run together.
pub fn proj_form(mut v: &'static Cv, mut s: &'static St, mut xs: Sexps) -> &'static Res {
    loop {
        if (not(null_p(xs)) && head_is_p(car(xs), str_lit("proj"))) {
            xs = onto(cdr(items(car(xs))), cdr(xs));
            continue;
        } else {
            let found = if null_p(xs) {
                nil::<&'static Bind>()
            } else {
                let tagcase_ = car(xs);
                match *tagcase_ {
                    Sexp::Sym(n, f, p) => {
                        let b = find_bind(n, cv_binds(v));
                        if null_p(b) {
                            find_bind(n, control_binds(v))
                        } else {
                            b
                        }
                    }
                    _ => {
                        let other = tagcase_;
                        nil::<&'static Bind>()
                    }
                }
            };
            if null_p(found) {
                return match refuse(v, str_lit("(proj f arg ...) of a poly procedure named")) {};
            } else {
                let tagcase_ = car(found);
                match *tagcase_ {
                    Bind::Bind(n, sc, wher) => {
                        let tagcase_ = sc;
                        match *tagcase_ {
                            Scheme::Scheme(tvars, t) => {
                                if not(i64_eq(size(tvars), size(cdr(xs)))) {
                                    return match refuse(v, string_append(str_lit("a proj of "), string_append(n, str_lit(" given the wrong number of arguments")))) {};
                                } else {
                                    bounds_kept(v, s, n, lambda1(move |x: Str| {
                                        projected(v, tvars, cdr(xs), ty_var(x))
                                    }));
                                    return res(projected(v, tvars, cdr(xs), t), naming_effs(s, n, wher, t, cv_group(v)), proj_needs(v, s, n, tvars, cdr(xs)));
                                }
                            }
                        }
                    }
                }
            }
        }
    }
}

/// A procedure's regions within its places (C40), `(r region p)`, given
/// regions that keep their bounds: `r`'s the place's, or bound inside
/// it, or within it, so that it will not outlive it, as FX-26 has it.
pub fn bounds_kept(v: &'static Cv, s: &'static St, n: Str, region_of_binder: &'static dyn Fn(Str) -> &'static Ty) -> () {
    map(lambda1(move |rest: Str| {
        let ws = read_all(string_chars(rest), str_lit(""), 1i64);
        let r = {
            let tagcase_ = walk(s, region_of_binder(sym_name(car(ws))));
            match *tagcase_ {
                Ty::TyVar(x) => {
                    x
                }
                _ => {
                    let other = tagcase_;
                    str_lit("")
                }
            }
        };
        let p = {
            let tagcase_ = walk(s, region_of_binder(sym_name(second(ws))));
            match *tagcase_ {
                Ty::TyVar(x) => {
                    x
                }
                _ => {
                    let other = tagcase_;
                    str_lit("")
                }
            }
        };
        if (string_eq_p(r, str_lit("")) || string_eq_p(p, str_lit("")) || string_eq_p(r, p) || string_member_p(string_append(str_lit("%within "), string_append(r, string_append(str_lit(" "), p))), cv_tvars(v)) || bound_before_p(r, string_append(str_lit("%place "), p), cv_tvars(v))) {
            ()
        } else {
            match refuse(v, string_append(str_lit("a region given within a place it could outlive: "), string_append(r, string_append(str_lit(" is bound outside "), p)))) {}
        }
    }), facts_after(cv_facts(v), string_append(str_lit("region-within "), string_append(n, str_lit(" ")))));
    ()
}

/// A proj's needs: what the procedure makes in each place, at the
/// places and types given (C34), noted as a call's are.
pub fn proj_needs(v: &'static Cv, s: &'static St, n: Str, tvars: Strings, args: Sexps) -> &'static St {
    let go__knot = knot::<&'static dyn Fn(&'static St, Strings) -> &'static St>();
    let go = lambda2(move |mut s: &'static St, mut needs: Strings| {
        loop {
            if null_p(needs) {
                return s;
            } else {
                let ws = read_all(string_chars(car(needs)), str_lit(""), 1i64);
                let place = projected(v, tvars, args, ty_var(sym_name(car(ws))));
                let need = projected(v, tvars, args, parse_type(v, onto(map(lambda1(move |x: Str| {
                    string_append(str_lit("%place "), x)
                }), tvars), tvars), third(ws)));
                (s, needs) = (note_types(s, cv_file(v), cv_pos(v), string_append(str_lit("rneed-"), string_append(sym_name(second(ws)), string_append(str_lit("@"), region_string(s, place)))), kayak_rt::heap_cons(need, kayak_rt::nil())), cdr(needs));
                continue;
            }
        }
    });
    go__knot.set(go);
    go(s, facts_after(cv_facts(v), string_append(str_lit("place-needs "), string_append(n, str_lit(" ")))))
}

pub fn projected(mut v: &'static Cv, mut tvars: Strings, mut args: Sexps, mut t: &'static Ty) -> &'static Ty {
    loop {
        if null_p(tvars) {
            return t;
        } else {
            (tvars, args, t) = (cdr(tvars), cdr(args), replace_var(car(tvars), if char_eq_p(string_ref_i64(car(tvars), 0i64), '\'') {
                parse_region(v, cv_tvars(v), car(args))
            } else if char_eq_p(string_ref_i64(car(tvars), 0i64), '~') {
                effect_row(kayak_rt::heap_cons(str_lit("~!"), parse_effect(v, cv_tvars(v), car(args))))
            } else {
                parse_type(v, cv_tvars(v), car(args))
            }, t));
            continue;
        }
    }
}

/// `(rlambda r params body ...)` (C38): a closure made in the place `r`,
/// whose latent effect therefore reads `r`, as FX-26 has it; its making
/// allocates there. In Rust a closure as a `lambda`'s is, kept as long
/// as anything wants it: where its memory is is all that differs.
pub fn rlambda_form(v: &'static Cv, s: &'static St, e: &'static Sexp, xs: Sexps, expected: Tys) -> &'static Res {
    if i64_lt(size(xs), 3i64) {
        match refuse(v, str_lit("(rlambda r params body ...)")) {}
    } else {
        let r = place_of(v, s, car(xs));
        let read = string_append(str_lit("read:"), region_string(s, r));
        let lam = lst(kayak_rt::heap_cons(sym(str_lit("lambda"), str_lit(""), 0i64), cdr(xs)), datum_file(e), 0i64, datum_pos(e));
        let tagcase_ = if (not(null_p(expected)) && proc_type_p(s, car(expected))) {
            let tagcase_ = walk(s, car(expected));
            match *tagcase_ {
                Ty::TyProc(ees, eps, er) => {
                    if not(string_member_p(read, map(lambda1(move |x: Str| {
                        resolve_atom(s, x)
                    }), ees))) {
                        match refuse(v, string_append(str_lit("an rlambda's latent effect reads its place, which the type expected does not: "), show_ty(s, car(expected)))) {}
                    } else {
                        check(v, s, lam, car(expected))
                    }
                }
                _ => {
                    let other = tagcase_;
                    check(v, s, lam, car(expected))
                }
            }
        } else {
            let tagcase_ = synth(v, s, lam);
            match *tagcase_ {
                Res::Res(t, es, s) => {
                    let tagcase_ = walk(s, t);
                    match *tagcase_ {
                        Ty::TyProc(les, ps, rt) => {
                            res(ty_proc(effs_union(kayak_rt::heap_cons(read, kayak_rt::nil()), les), ps, rt), es, s)
                        }
                        _ => {
                            let other = tagcase_;
                            res(t, es, s)
                        }
                    }
                }
            }
        };
        match *tagcase_ {
            Res::Res(t, es, s) => {
                res(t, effs_union(kayak_rt::heap_cons(string_append(str_lit("alloc:"), region_string(s, r)), kayak_rt::nil()), es), s)
            }
        }
    }
}

pub fn letrec_lambdas(v: &'static Cv, s: &'static St, bindings: Sexps) -> &'static Res {
    if null_p(bindings) {
        res(ty_unit(), nil::<Str>(), s)
    } else {
        let ys = items(car(bindings));
        if not((head_is_p(third(ys), str_lit("lambda")) || head_is_p(third(ys), str_lit("rlambda")))) {
            match refuse(v, str_lit("a letrec binds only lambdas")) {}
        } else {
            let tagcase_ = check(v, s, third(ys), parse_type(v, cv_tvars(v), second(ys)));
            match *tagcase_ {
                Res::Res(t, es, s) => {
                    letrec_lambdas(v, s, cdr(bindings))
                }
            }
        }
    }
}

/// A lambda with nothing expected: its parameters' types written.
pub fn synth_lambda(v: &'static Cv, s: &'static St, params: Sexps, forms: Sexps) -> &'static Res {
    let types = map(lambda1(move |p: &'static Sexp| {
        let tagcase_ = p;
        match *tagcase_ {
            Sexp::Lst(pt, src_file, src_line, src_pos) => {
                parse_type(v, cv_tvars(v), second(pt))
            }
            _ => {
                let other = tagcase_;
                match refuse(v, string_append(str_lit("a lambda with nothing expected needs its parameters' types: "), show_sexp(other))) {}
            }
        }
    }), params);
    if any_p(lambda1(move |p: &'static Ty| {
        not(null_p(module_spec(v, p)))
    }), types) {
        match refuse(v, str_lit("a module parameter is a top-level procedure's (C24)")) {}
    } else {
        let tagcase_ = body(with_binds(v, bind_params(v, params, types)), s, forms, nil::<&'static Ty>());
        match *tagcase_ {
            Res::Res(r, es, s) => {
                res(ty_proc(es, types, r), nil::<Str>(), noted_lambda(v, s, es))
            }
        }
    }
}

/// No two module parameters named alike in Rust, their type parameters
/// camel-cased (`m` and `m-` are both `Mod_M`).
pub fn module_params_apart(v: &'static Cv, params: Sexps, types: Tys, s: &'static St) -> &'static St {
    if repeated_p(concat(map(lambda1(move |n: Str| {
        the::<Strings>(kayak_rt::heap_cons(camel(n), kayak_rt::nil()))
    }), module_param_names(v, s, params, types)))) {
        match refuse(v, str_lit("two module parameters named alike in Rust (camel-cased, as `m` and `m-`)")) {}
    } else {
        s
    }
}

pub fn module_param_names(v: &'static Cv, s: &'static St, params: Sexps, types: Tys) -> Strings {
    if (null_p(params) || null_p(types)) {
        nil::<Str>()
    } else {
        let rest = module_param_names(v, s, cdr(params), cdr(types));
        if null_p(module_spec(v, walk(s, car(types)))) {
            rest
        } else {
            kayak_rt::heap_cons(param_name(car(params)), rest)
        }
    }
}

pub fn check_lambda(v: &'static Cv, s: &'static St, params: Sexps, forms: Sexps, expected: &'static Ty) -> &'static Res {
    let tagcase_ = expected;
    match *tagcase_ {
        Ty::TyProc(ees, eps, er) => {
            if not(i64_eq(size(params), size(eps))) {
                match refuse(v, str_lit("a lambda of the wrong number of parameters")) {}
            } else {
                let s = module_params_apart(v, params, eps, check_written_params(v, s, params, eps));
                if (not(null_p(module_spec(v, walk(s, er)))) || (any_p(lambda1(move |p: &'static Ty| {
                    not(null_p(module_spec(v, walk(s, p))))
                }), eps) && not(top_lambda_p(v)))) {
                    match refuse(v, str_lit("a module parameter is a top-level procedure's, and no procedure gives a module back (C24)")) {}
                } else {
                    let tagcase_ = body(with_binds(v, kayak_rt::heap_cons(bind(str_lit("%toplambda"), scheme(nil::<Str>(), ty_unit()), str_lit("no")), bind_params(v, params, eps))), s, forms, kayak_rt::heap_cons(er, kayak_rt::nil()));
                    match *tagcase_ {
                        Res::Res(r, es, s) => {
                            if not(null_p(fit_effs(s, es, ees))) {
                                let s = car(fit_effs(s, es, ees));
                                let s = if any_p(lambda1(move |p: &'static Ty| {
                                    (has_meta_p(s, p) || has_var_p(s, p))
                                }), eps) {
                                    s
                                } else {
                                    note_fact(s, cv_file(v), cv_pos(v), string_append(str_lit("param-types "), show_sexp(lst(map(lambda1(move |p: &'static Ty| {
                                        ty_sexp(v, s, zonk(s, p))
                                    }), eps), str_lit(""), 0i64, 0i64))))
                                };
                                res(expected, nil::<Str>(), noted_lambda(v, s, ees))
                            } else {
                                match refuse(v, string_append(str_lit("a lambda whose effect "), string_append(show_effs(es), string_append(str_lit(" is not within "), show_effs(ees))))) {}
                            }
                        }
                    }
                }
            }
        }
        _ => {
            let other = tagcase_;
            match refuse(v, str_lit("a lambda where no procedure is expected")) {}
        }
    }
}

/// A lambda's body's effect, the body checked against the type `t`'s
/// parameters and result, but not its effect: what `define*` finds.
pub fn lambda_effects(v: &'static Cv, s: &'static St, params: Sexps, forms: Sexps, t: &'static Ty) -> &'static Res {
    let tagcase_ = t;
    match *tagcase_ {
        Ty::TyProc(ees, eps, er) => {
            if not(i64_eq(size(params), size(eps))) {
                match refuse(v, str_lit("a lambda of the wrong number of parameters")) {}
            } else {
                body(with_binds(v, bind_params(v, params, eps)), check_written_params(v, s, params, eps), forms, kayak_rt::heap_cons(er, kayak_rt::nil()))
            }
        }
        _ => {
            let other = tagcase_;
            match refuse(v, str_lit("a lambda where no procedure is expected")) {}
        }
    }
}

/// A parameter written `(x T)` must be of the type expected. One written
/// `x` must have its type known already, from the arguments before the
/// lambda: rustc, which checks a call's arguments in order, finds a
/// closure's parameter types no other way.
pub fn check_written_params(mut v: &'static Cv, mut s: &'static St, mut params: Sexps, mut types: Tys) -> &'static St {
    loop {
        if null_p(params) {
            return s;
        } else {
            (s, params, types) = ({
                let tagcase_ = car(params);
                match *tagcase_ {
                    Sexp::Lst(pt, src_file, src_line, src_pos) => {
                        fits(v, s, car(types), parse_type(v, cv_tvars(v), second(pt)))
                    }
                    _ => {
                        let other = tagcase_;
                        if has_meta_p(s, car(types)) {
                            match refuse(v, string_append(str_lit("the type of the lambda's parameter "), string_append(show_sexp(other), str_lit(" is not known from the arguments before it: write it as (x T)")))) {}
                        } else {
                            s
                        }
                    }
                }
            }, cdr(params), cdr(types));
            continue;
        }
    }
}

/// A call of a name: a procedure in this group is `spin`, one that is a
/// local's value is a call of a procedure not known, so `spin` too.
pub fn synth_call(v: &'static Cv, s: &'static St, h: Str, args: Sexps, expected: Tys) -> &'static Res {
    let found = find_bind(h, cv_binds(v));
    if keyword_p(h) {
        match refuse(v, string_append(str_lit("("), string_append(h, str_lit(" ...) is FX-26's form, which KFX does not have, or a call of a local named by that keyword")))) {}
    } else if (null_p(found) && string_eq_p(h, str_lit("abort-current-continuation"))) {
        abort_call(v, s, args)
    } else if (null_p(found) && string_eq_p(h, str_lit("apply")) && i64_eq(size(args), 2i64)) {
        // `(apply f xs)` (C71): a variadic procedure on a list's elements.
        let tagcase_ = synth(v, s, car(args));
        match *tagcase_ {
            Res::Res(ft, es0, s0) => {
                let tagcase_ = walk(s0, ft);
                match *tagcase_ {
                    Ty::TyData(d, parts) => {
                        if not(string_eq_p(d, str_lit("%vsubr"))) {
                            match refuse(v, str_lit("apply of no variadic procedure")) {}
                        } else {
                            let tagcase_ = synth(v, s0, second(args));
                            match *tagcase_ {
                                Res::Res(lt, es1, s1) => {
                                    let tagcase_ = walk(s1, lt);
                                    match *tagcase_ {
                                        Ty::TyList(el, r) => {
                                            res(car(cdr(cdr(parts))), effs_union({
                                                let tagcase_ = car(parts);
                                                match *tagcase_ {
                                                    Ty::TyProc(e, ps, x) => {
                                                        e
                                                    }
                                                    _ => {
                                                        let other = tagcase_;
                                                        nil::<Str>()
                                                    }
                                                }
                                            }, effs_union(kayak_rt::heap_cons(string_append(str_lit("read:"), region_string(s1, r)), kayak_rt::nil()), effs_union(es0, es1))), fits(v, s1, el, car(cdr(parts))))
                                        }
                                        _ => {
                                            let other = tagcase_;
                                            match refuse(v, str_lit("apply of a variadic procedure to no list")) {}
                                        }
                                    }
                                }
                            }
                        }
                    }
                    _ => {
                        let other = tagcase_;
                        match refuse(v, str_lit("apply of no variadic procedure")) {}
                    }
                }
            }
        }
    } else if ((string_eq_p(h, str_lit("null?")) || string_eq_p(h, str_lit("pair?"))) && i64_eq(size(args), 1i64) && not(null_p(found)) && {
        let tagcase_ = car(found);
        match *tagcase_ {
            Bind::Bind(n, sc, w) => {
                string_eq_p(w, str_lit("prim"))
            }
        }
    } && {
        let tagcase_ = car(args);
        match *tagcase_ {
            Sexp::Sym(n, f, p) => {
                let b = find_bind(n, cv_binds(v));
                (not(null_p(b)) && {
                    let tagcase_ = car(b);
                    match *tagcase_ {
                        Bind::Bind(n2, sc, w) => {
                            let tagcase_ = sc;
                            match *tagcase_ {
                                Scheme::Scheme(tv, t) => {
                                    string_member_p(shape_of(walk(s, t)), kayak_rt::heap_cons(str_lit("union"), kayak_rt::heap_cons(str_lit("pair"), kayak_rt::heap_cons(str_lit("nil"), kayak_rt::nil()))))
                                }
                            }
                        }
                    }
                })
            }
            _ => {
                let other = tagcase_;
                false
            }
        }
    }) {
        // FX-26's `null?` and `pair?` of any value (C68): of a local of a
        // union, a pair or `nil`, which KFX's, of a list, would not take.
        let tagcase_ = synth(v, s, car(args));
        match *tagcase_ {
            Res::Res(t, es, s2) => {
                res(ty_bool(), es, s2)
            }
        }
    } else if ((string_eq_p(h, str_lit("car")) || string_eq_p(h, str_lit("cdr"))) && i64_eq(size(args), 1i64) && not(null_p(local_pair(v, s, car(args))))) {
        // Of a local known to be a pair (C68): its head or its tail, of any
        // type, not only a list's.
        let tagcase_ = car(local_pair(v, s, car(args)));
        match *tagcase_ {
            Ty::TyData(d, parts) => {
                res(if string_eq_p(h, str_lit("car")) {
                    car(parts)
                } else {
                    car(cdr(parts))
                }, kayak_rt::heap_cons(string_append(str_lit("read:"), region_string(s, car(cdr(cdr(parts))))), kayak_rt::nil()), s)
            }
            _ => {
                let other = tagcase_;
                match refuse(v, str_lit("a pair that is none")) {}
            }
        }
    } else if (string_eq_p(h, str_lit("cons")) && i64_eq(size(args), 2i64) && not(null_p(expected)) && not(null_p(pair_expected(s, car(expected))))) {
        // Where a pair is expected (C68): its head and tail checked against
        // its own, of any types.
        let tagcase_ = car(pair_expected(s, car(expected)));
        match *tagcase_ {
            Ty::TyData(d, parts) => {
                let tagcase_ = check(v, s, car(args), car(parts));
                match *tagcase_ {
                    Res::Res(t1, es1, s1) => {
                        let tagcase_ = check(v, s1, second(args), car(cdr(parts)));
                        match *tagcase_ {
                            Res::Res(t2, es2, s2) => {
                                res(car(pair_expected(s, car(expected))), effs_union(kayak_rt::heap_cons(string_append(str_lit("alloc:"), region_string(s2, car(cdr(cdr(parts))))), kayak_rt::nil()), effs_union(es1, es2)), s2)
                            }
                        }
                    }
                }
            }
            _ => {
                let other = tagcase_;
                match refuse(v, str_lit("a pair that is none")) {}
            }
        }
    } else if (null_p(found) && string_eq_p(h, str_lit("abort-with-continuation"))) {
        suspend_call(v, s, args, expected)
    } else if (null_p(found) && string_eq_p(h, str_lit("make-continuation-prompt-tag"))) {
        make_tag_call(v, s, args, expected)
    } else if (null_p(found) && (string_eq_p(h, str_lit("rcons")) || string_eq_p(h, str_lit("rnew")))) {
        region_alloc_call(v, s, h, args, expected)
    } else if null_p(found) {
        match refuse(v, string_append(str_lit("nothing is named "), h)) {}
    } else if (nat_op_p(h) && prim_p(car(found)) && i64_eq(size(args), 2i64) && nat_args_p(v, s, args)) {
        let tagcase_ = call_args(v, s, args, kayak_rt::heap_cons(ty_nat(), kayak_rt::heap_cons(ty_nat(), kayak_rt::nil())), nil::<i64>());
        match *tagcase_ {
            Res::Res(u, es, s) => {
                res(ty_nat(), es, if null_p(expected) {
                    s
                } else {
                    fits(v, s, ty_nat(), car(expected))
                })
            }
        }
    } else {
        let tagcase_ = car(found);
        match *tagcase_ {
            Bind::Bind(n, sc, wher) => {
                let from = st_next(s);
                let tagcase_ = instantiate(s, sc);
                match *tagcase_ {
                    Inst::Inst(t, s, regions, effects) => {
                        place_needed(v, h, wher, sc, from, regions_freshened(v, h, wher, regions, static_instance(v, h, wher, binder_metas(from, st_next(s), onto(effects, regions)), poly_settled(v, h, wher, args, binder_metas(from, st_next(s), onto(effects, regions)), result_only_p(s, t, binder_metas(from, st_next(s), onto(effects, regions))), void_call(v, (string_eq_p(h, str_lit("error")) && string_eq_p(wher, str_lit("prim"))), (not(null_p(expected)) && {
                            let tagcase_ = walk(s, car(expected));
                            match *tagcase_ {
                                Ty::TyMeta(k) => {
                                    true
                                }
                                _ => {
                                    let other = tagcase_;
                                    false
                                }
                            }
                        }), poly_self_application(v, sc, t, knot_free_call(v, synth_call_of(v, s, res(t, nil::<Str>(), s), args, regions, expected, effs_union(if string_eq_p(wher, str_lit("global")) {
                            kayak_rt::heap_cons(string_append(str_lit("g:"), h), kayak_rt::nil())
                        } else {
                            nil::<Str>()
                        }, if (string_eq_p(wher, str_lit("rec")) || (string_eq_p(wher, str_lit("local")) && self_applicable_p(v, s, t)) || (string_member_p(h, cv_group(v)) && (string_eq_p(wher, str_lit("global")) || string_eq_p(wher, str_lit("item"))))) {
                            kayak_rt::heap_cons(str_lit("spin"), kayak_rt::nil())
                        } else {
                            nil::<Str>()
                        })))))))))
                    }
                }
            }
        }
    }
}

/// A procedure's call at types, each a Rust type parameter `A: Copy +
/// 'static`: none may be at a region with a lifetime, a `letrena`'s, a
/// place's, a region binder's (C42), which `'static` is not.
pub fn static_instance(v: &'static Cv, h: Str, wher: Str, metas: List<i64>, r: &'static Res) -> &'static Res {
    let tagcase_ = r;
    match *tagcase_ {
        Res::Res(t, es, s) => {
            if ((string_eq_p(wher, str_lit("global")) || string_eq_p(wher, str_lit("item")) || string_eq_p(wher, str_lit("rec"))) && any_p(lambda1(move |k: i64| {
                string_has_p(show_ty(s, ty_meta(k)), str_lit("'"))
            }), metas)) {
                match refuse(v, string_append(str_lit("a call of "), string_append(h, str_lit(" at a type over a region with a lifetime, where its Rust type parameter is 'static (C42)")))) {}
            } else {
                r
            }
        }
    }
}

/// A poly's call: a region binder its arguments and what its place
/// expects did not say made fresh, as FX-26 makes it (its
/// `default_regions`): a list made by `cons` and found by itself is at a
/// region of its own, not one a later use may choose.
pub fn regions_freshened(v: &'static Cv, h: Str, wher: Str, regions: List<i64>, r: &'static Res) -> &'static Res {
    let tagcase_ = r;
    match *tagcase_ {
        Res::Res(t, es, s) => {
            res(t, es, {
                let go__knot = knot::<&'static dyn Fn(&'static St, List<i64>) -> &'static St>();
                let go = lambda2(move |mut s: &'static St, mut ks: List<i64>| {
                    loop {
                        if null_p(ks) {
                            return s;
                        } else {
                            (s, ks) = ({
                                let tagcase_ = walk(s, ty_meta(car(ks)));
                                match *tagcase_ {
                                    Ty::TyMeta(k) => {
                                        solve(s, k, ty_rconst(str_lit("%fresh")))
                                    }
                                    _ => {
                                        let other = tagcase_;
                                        s
                                    }
                                }
                            }, cdr(ks));
                            continue;
                        }
                    }
                });
                go__knot.set(go);
                go(s, regions)
            })
        }
    }
}

/// A call of a procedure given places (C34): what it makes in each, its
/// `place-needs`, noted at the call as needs of the place it is given,
/// `rneed-kind@'r T`, `T` at the types it is called at.
pub fn place_needed(v: &'static Cv, h: Str, wher: Str, sc: &'static Scheme, from: i64, r: &'static Res) -> &'static Res {
    if (not(string_eq_p(wher, str_lit("global"))) || not(given_place_p(sc))) {
        r
    } else {
        let tagcase_ = r;
        match *tagcase_ {
            Res::Res(t, es, s) => {
                let tagcase_ = sc;
                match *tagcase_ {
                    Scheme::Scheme(tvars, ty) => {
                        let needs = facts_after(cv_facts(v), string_append(str_lit("place-needs "), string_append(h, str_lit(" "))));
                        bounds_kept(v, s, h, lambda1(move |x: Str| {
                            instantiated(tvars, from, ty_var(x))
                        }));
                        res(t, es, note_needs(v, s, tvars, from, needs))
                    }
                }
            }
        }
    }
}

pub fn note_needs(mut v: &'static Cv, mut s: &'static St, mut tvars: Strings, mut from: i64, mut needs: Strings) -> &'static St {
    loop {
        if null_p(needs) {
            return s;
        } else {
            let ws = read_all(string_chars(car(needs)), str_lit(""), 1i64);
            let place = sym_name(car(ws));
            let kind = sym_name(second(ws));
            let need = instantiated(tvars, from, parse_type(v, onto(map(lambda1(move |x: Str| {
                string_append(str_lit("%place "), x)
            }), tvars), tvars), third(ws)));
            let at = instantiated(tvars, from, ty_var(place));
            (s, needs) = (note_types(s, cv_file(v), cv_pos(v), string_append(str_lit("rneed-"), string_append(kind, string_append(str_lit("@"), region_string(s, at)))), kayak_rt::heap_cons(need, kayak_rt::nil())), cdr(needs));
            continue;
        }
    }
}

/// `t`, a callee's, its binders replaced by the inference variables its
/// call made for them, from `from` on, in order.
pub fn instantiated(mut tvars: Strings, mut from: i64, mut t: &'static Ty) -> &'static Ty {
    loop {
        if null_p(tvars) {
            return t;
        } else {
            (tvars, from, t) = (cdr(tvars), i64_plus(from, 1i64), replace_var(car(tvars), ty_meta(from), t));
            continue;
        }
    }
}

/// Whether a type binder of a procedure, `ks` as instantiated in `t`, is
/// in none of its parameters' types: its result's alone, which rustc
/// infers from no argument.
pub fn result_only_p(s: &'static St, t: &'static Ty, ks: List<i64>) -> bool {
    let tagcase_ = walk(s, t);
    match *tagcase_ {
        Ty::TyProc(es, ps, r) => {
            any_p(lambda1(move |k: i64| {
                not(any_p(lambda1(move |p: &'static Ty| {
                    occurs_p(s, k, p)
                }), ps))
            }), ks)
        }
        _ => {
            let other = tagcase_;
            false
        }
    }
}

/// A poly's call: its type binders, `ks`, each solved by the call, as
/// FX-26 has them (its arguments and what the call's place expects; not
/// what follows), but `null?`'s of a name or an `error`, whose binder in
/// FX-26 is its argument's type whole; and the types a procedure of the
/// program's is called at noted, for the turbofish, where a binder is
/// its result's alone.
pub fn poly_settled(v: &'static Cv, h: Str, wher: Str, args: Sexps, ks: List<i64>, fish: bool, r: &'static Res) -> &'static Res {
    let tagcase_ = r;
    match *tagcase_ {
        Res::Res(t, es, s) => {
            let open = any_p(lambda1(move |k: i64| {
                let tagcase_ = walk(s, ty_meta(k));
                match *tagcase_ {
                    Ty::TyMeta(j) => {
                        true
                    }
                    _ => {
                        let other = tagcase_;
                        false
                    }
                }
            }), ks);
            if ((string_eq_p(h, str_lit("car")) || string_eq_p(h, str_lit("cdr"))) && string_eq_p(wher, str_lit("prim")) && not(null_p(args)) && (head_is_p(car(args), str_lit("error")) || {
                let tagcase_ = car(args);
                match *tagcase_ {
                    Sexp::Sym(n, f, p) => {
                        let found = find_bind(n, cv_binds(v));
                        (not(null_p(found)) && {
                            let tagcase_ = car(found);
                            match *tagcase_ {
                                Bind::Bind(m, sc, w) => {
                                    let tagcase_ = sc;
                                    match *tagcase_ {
                                        Scheme::Scheme(tv, x) => {
                                            void_p(s, x)
                                        }
                                    }
                                }
                            }
                        })
                    }
                    _ => {
                        let other = tagcase_;
                        false
                    }
                }
            })) {
                // FX-26's `car` and `cdr` are over a pair, `(pairof t1 t2 r)`: of a
                // `void`, what the expected type does not say of the pair, nothing
                // does.
                match refuse(v, string_append(str_lit("a type "), string_append(h, str_lit(" is called at that nothing here says, as FX-26 finds it: say it, (the T ...)")))) {}
            } else if (open && not((string_eq_p(h, str_lit("null?")) && string_eq_p(wher, str_lit("prim")) && not(null_p(args)) && ({
                let tagcase_ = car(args);
                match *tagcase_ {
                    Sexp::Sym(n, f, p) => {
                        true
                    }
                    _ => {
                        let other = tagcase_;
                        false
                    }
                }
            } || head_is_p(car(args), str_lit("error")))))) {
                match refuse(v, string_append(str_lit("a type "), string_append(h, str_lit(" is called at that nothing here says, as FX-26 finds it: say it, (the T ...)")))) {}
            } else if open {
                // `null?`'s, written at the type FX-26 leaves open: `void`.
                res(t, es, note_turbofish(s, cv_file(v), cv_pos(v), map(lambda1(move |k: i64| {
                    ty_meta(k)
                }), ks)))
            } else if (string_eq_p(wher, str_lit("prim")) || null_p(ks) || not(fish)) {
                r
            } else {
                res(t, es, note_turbofish(s, cv_file(v), cv_pos(v), map(lambda1(move |k: i64| {
                    ty_meta(k)
                }), ks)))
            }
        }
    }
}

/// Whether each argument is a `nat` FX-26 keeps one through a sum: a
/// literal not negative, a name of a `nat`, or such a sum itself; not a
/// call's value or a `the`'s, a plain `nat`, which FX-26's `+` makes an
/// `int` (each literal is its own `(nat v)` to it). The finding is a
/// test, its state dropped.
pub fn nat_args_p(v: &'static Cv, s: &'static St, args: Sexps) -> bool {
    (null_p(args) || ({
        let tagcase_ = car(args);
        match *tagcase_ {
            Sexp::Num(k, f, p) => {
                (not(i64_lt(k, 0i64)) && not(i64_gt(k, 1152921504606846975i64)))
            }
            Sexp::Big(text, f, p) => {
                false
            }
            Sexp::Sym(n, f, p) => {
                let tagcase_ = synth(v, s, car(args));
                match *tagcase_ {
                    Res::Res(t, es, s2) => {
                        nat_p(s2, t)
                    }
                }
            }
            Sexp::Lst(xs, f, l, p) => {
                (head_is_p(car(args), str_lit("+")) && not(null_p(find_bind(str_lit("+"), cv_binds(v)))) && {
                    let tagcase_ = car(find_bind(str_lit("+"), cv_binds(v)));
                    match *tagcase_ {
                        Bind::Bind(n, sc, w) => {
                            string_eq_p(w, str_lit("prim"))
                        }
                    }
                } && nat_args_p(v, s, cdr(xs)))
            }
            _ => {
                let other = tagcase_;
                false
            }
        }
    } && nat_args_p(v, s, cdr(args))))
}

/// `(abort-current-continuation tag v)`: to the innermost prompt of
/// `tag`, with `v`; a `goto` on the tag's region, and of type `void`.
pub fn abort_call(v: &'static Cv, s: &'static St, args: Sexps) -> &'static Res {
    if not(i64_eq(size(args), 2i64)) {
        match refuse(v, str_lit("abort-current-continuation takes a tag and a value")) {}
    } else {
        let tagcase_ = synth(v, s, car(args));
        match *tagcase_ {
            Res::Res(t, es0, s) => {
                let tagcase_ = walk(s, t);
                match *tagcase_ {
                    Ty::TyTag(a, h, d, r) => {
                        let tagcase_ = check(v, s, second(args), h);
                        match *tagcase_ {
                            Res::Res(u, es1, s) => {
                                res(ty_void(), effs_union(kayak_rt::heap_cons(string_append(str_lit("goto:"), region_string(s, r)), kayak_rt::nil()), effs_union(es0, es1)), s)
                            }
                        }
                    }
                    _ => {
                        let other = tagcase_;
                        match refuse(v, string_append(str_lit("an abort to a "), string_append(show_ty(s, t), str_lit(", no prompt-tag")))) {}
                    }
                }
            }
        }
    }
}

/// `(abort-with-continuation tag (lambda ((k K)) body))` (kfx/prelude.fx,
/// C45): the rest up to `tag`'s prompt, `k`, resumable once, of `K`, a
/// `(subr (maxeff D (goto R) (comefrom R) (read R) (write R)) (V) A)`
/// for the tag's `(prompt-tag A H D R)`; an abort there with `body`'s
/// value, an `H`. Its value is a `V`, what `k` is resumed with; its
/// effect, the body's, control and allocation at `R`, and the prelude's
/// global read. The body runs as the prompt takes `k`: KFX has it
/// neither abort nor suspend.
pub fn suspend_call(v: &'static Cv, s: &'static St, args: Sexps, expected: Tys) -> &'static Res {
    if not(i64_eq(size(args), 2i64)) {
        match refuse(v, str_lit("abort-with-continuation takes a tag and a lambda")) {}
    } else if not((head_is_p(second(args), str_lit("lambda")) && i64_eq(size(items(second(items(second(args))))), 1i64))) {
        match refuse(v, str_lit("abort-with-continuation's second argument is a lambda of one parameter, in KFX")) {}
    } else {
        let tagcase_ = synth(v, s, car(args));
        match *tagcase_ {
            Res::Res(tt, es0, s) => {
                let tagcase_ = walk(s, tt);
                match *tagcase_ {
                    Ty::TyTag(a, h, d, r) => {
                        let rn = region_string(s, r);
                        let lam = items(second(args));
                        let param = car(items(second(lam)));
                        let tagcase_ = param;
                        match *tagcase_ {
                            Sexp::Lst(pt, pf, pl, pp) => {
                                let kt = parse_type(v, cv_tvars(v), second(pt));
                                let tagcase_ = walk(s, kt);
                                match *tagcase_ {
                                    Ty::TyProc(kes, kps, ka) => {
                                        if not(i64_eq(size(kps), 1i64)) {
                                            match refuse(v, str_lit("a continuation takes one value")) {}
                                        } else {
                                            let want = effs_union(d, kayak_rt::heap_cons(string_append(str_lit("goto:"), rn), kayak_rt::heap_cons(string_append(str_lit("comefrom:"), rn), kayak_rt::heap_cons(string_append(str_lit("read:"), rn), kayak_rt::heap_cons(string_append(str_lit("write:"), rn), kayak_rt::nil())))));
                                            let s = fits(v, s, ka, a);
                                            if not((effs_within_p(kes, want) && effs_within_p(want, kes))) {
                                                match refuse(v, string_append(str_lit("the continuation's effect is the tag's bound, and control, reading and writing at its region: "), string_append(show_effs(want), string_append(str_lit(", not "), show_effs(kes))))) {}
                                            } else {
                                                let tagcase_ = lambda_effects(v, s, items(second(lam)), cdr(cdr(lam)), ty_proc(nil::<Str>(), kayak_rt::heap_cons(kt, kayak_rt::nil()), h));
                                                match *tagcase_ {
                                                    Res::Res(u, es1, s) => {
                                                        if escapes_p(es1) {
                                                            match refuse(v, str_lit("abort-with-continuation's lambda may abort or suspend, which KFX has not")) {}
                                                        } else {
                                                            let s = if null_p(expected) {
                                                                s
                                                            } else {
                                                                fits(v, s, car(kps), car(expected))
                                                            };
                                                            res(car(kps), effs_union(kayak_rt::heap_cons(string_append(str_lit("goto:"), rn), kayak_rt::heap_cons(string_append(str_lit("comefrom:"), rn), kayak_rt::heap_cons(string_append(str_lit("alloc:"), rn), kayak_rt::heap_cons(str_lit("g:abort-with-continuation"), kayak_rt::nil())))), effs_union(es0, es1)), s)
                                                        }
                                                    }
                                                }
                                            }
                                        }
                                    }
                                    _ => {
                                        let other = tagcase_;
                                        match refuse(v, str_lit("a continuation's type is a subr")) {}
                                    }
                                }
                            }
                            _ => {
                                let other = tagcase_;
                                match refuse(v, str_lit("abort-with-continuation's parameter is written (k K), its type said")) {}
                            }
                        }
                    }
                    _ => {
                        let other = tagcase_;
                        match refuse(v, string_append(str_lit("a suspension to a "), string_append(show_ty(s, tt), str_lit(", no prompt-tag")))) {}
                    }
                }
            }
        }
    }
}

/// `(make-continuation-prompt-tag)`: its type, said where it is made.
pub fn make_tag_call(v: &'static Cv, s: &'static St, args: Sexps, expected: Tys) -> &'static Res {
    if not(null_p(args)) {
        match refuse(v, str_lit("make-continuation-prompt-tag takes nothing")) {}
    } else if null_p(expected) {
        match refuse(v, str_lit("a prompt tag whose type nothing says: write (the (prompt-tag A H D R) (make-continuation-prompt-tag))")) {}
    } else {
        let tagcase_ = walk(s, car(expected));
        match *tagcase_ {
            Ty::TyTag(a, h, d, r) => {
                res(car(expected), kayak_rt::heap_cons(string_append(str_lit("alloc:"), region_string(s, r)), kayak_rt::nil()), s)
            }
            _ => {
                let other = tagcase_;
                match refuse(v, str_lit("a prompt tag where none is expected")) {}
            }
        }
    }
}

/// `(prompt tag body handler)`, as FX-26 has it: the body of the tag's
/// answer type, its effect, but for control on the tag's region, within
/// the tag's bound; an abort to the tag runs the handler. The prompt
/// removes the `goto` on the region when the body can reach no other tag
/// there: when nothing it names but the tag has a type that mentions the
/// region (every name, bound in it or not: stricter than FX-26's free
/// variables, never laxer).
pub fn prompt_form(v: &'static Cv, s: &'static St, xs: Sexps, expected: Tys) -> &'static Res {
    let tagcase_ = synth(v, s, car(xs));
    match *tagcase_ {
        Res::Res(tt, es0, s) => {
            let tagcase_ = walk(s, tt);
            match *tagcase_ {
                Ty::TyTag(a, h, d, r) => {
                    let rn = region_string(s, r);
                    let tagcase_ = check(v, s, second(xs), a);
                    match *tagcase_ {
                        Res::Res(u, es1, s) => {
                            if not(effs_within_p(masked_goto(es1, rn), d)) {
                                match refuse(v, string_append(str_lit("the tag allows its delimited computations "), string_append(show_effs(d), string_append(str_lit(", and this body also has "), show_effs(masked_goto(es1, rn)))))) {}
                            } else {
                                let tagcase_ = handler_of(v, s, third(xs), h, a);
                                match *tagcase_ {
                                    Res::Res(u2, es2, s) => {
                                        let delimits = not(reaches_p(v, s, second(xs), car(xs), rn));
                                        let s = if delimits {
                                            note_fact(s, cv_file(v), cv_pos(v), str_lit("delimits"))
                                        } else {
                                            s
                                        };
                                        let s = if (delimits && not(escapes_p(masked_goto(es1, rn)))) {
                                            note_fact(s, cv_file(v), cv_pos(v), str_lit("contains"))
                                        } else {
                                            s
                                        };
                                        let s = if suspends_p(es1) {
                                            note_fact(s, cv_file(v), cv_pos(v), str_lit("suspending-body"))
                                        } else {
                                            s
                                        };
                                        let s = if null_p(expected) {
                                            s
                                        } else {
                                            fits(v, s, a, car(expected))
                                        };
                                        res(a, effs_union(es0, effs_union(es2, if delimits {
                                            masked_goto(es1, rn)
                                        } else {
                                            es1
                                        })), s)
                                    }
                                }
                            }
                        }
                    }
                }
                _ => {
                    let other = tagcase_;
                    match refuse(v, string_append(str_lit("a prompt of a "), string_append(show_ty(s, tt), str_lit(", no prompt-tag")))) {}
                }
            }
        }
    }
}

/// A prompt's handler, a lambda from the payload to the answer: its
/// body's effect is the prompt's, since the prompt calls it. One that
/// may abort or suspend is noted so, as any lambda is, and its call is
/// `?`ed and awaited (C46).
pub fn handler_of(v: &'static Cv, s: &'static St, e: &'static Sexp, h: &'static Ty, a: &'static Ty) -> &'static Res {
    if not(head_is_p(e, str_lit("lambda"))) {
        match refuse(v, str_lit("a prompt's handler is a lambda, in KFX")) {}
    } else {
        let lam = items(e);
        let tagcase_ = lambda_effects(v, s, items(second(lam)), cdr(cdr(lam)), ty_proc(nil::<Str>(), kayak_rt::heap_cons(h, kayak_rt::nil()), a));
        match *tagcase_ {
            Res::Res(u, es, s) => {
                res(a, es, {
                    let tagcase_ = e;
                    match *tagcase_ {
                        Sexp::Lst(xs, f, l, p) => {
                            noted_lambda(near(v, f, l, p), s, es)
                        }
                        _ => {
                            let other = tagcase_;
                            s
                        }
                    }
                })
            }
        }
    }
}

/// A call of the procedure `callee` is: its result fitted to the type
/// `expected`, if one is, then its arguments checked against its
/// parameters, in order (a `list` given for a parameter whose type is an
/// instance's found by itself, as FX-26 finds it); its effect, the callee's latent effect, the
/// arguments' and `more`. In order, not lambdas last as FX-26 does,
/// since rustc finds a closure's parameter types only from what comes
/// before it: see `check-written-params`. A procedure expected bounds
/// the result from above, as FX-26 has it: fitted after the arguments,
/// which say what it is, one that cannot abort then lifted (C35). A
/// list it makes, found by itself, at a region nothing said is at a
/// fresh one, as FX-26's is: not one a later use may choose (C36).
pub fn synth_call_of(v: &'static Cv, s: &'static St, callee: &'static Res, args: Sexps, regions: List<i64>, expected: Tys, more: Strings) -> &'static Res {
    let tagcase_ = callee;
    match *tagcase_ {
        Res::Res(t, es0, s) => {
            let tagcase_ = vsubr_as_proc(composable_as_proc(s, walk(s, t)), size(args));
            match *tagcase_ {
                Ty::TyProc(latent, ps, r) => {
                    if not(i64_eq(size(ps), size(args))) {
                        match refuse(v, string_append(str_lit("a call of the wrong number of arguments: "), show_sexps(args))) {}
                    } else {
                        let tagcase_ = {
                            let s1 = if (null_p(expected) || proc_type_p(s, car(expected))) {
                                s
                            } else {
                                fits(v, s, r, car(expected))
                            };
                            call_args(v, s1, args, ps, fixed_by(s, s1, concat(map(&metas_of, ps))))
                        };
                        match *tagcase_ {
                            Res::Res(u, es1, s0) => {
                                let s = if null_p(expected) {
                                    freshened(s0, r)
                                } else {
                                    if proc_type_p(s0, car(expected)) {
                                        fits(v, s0, r, car(expected))
                                    } else {
                                        s0
                                    }
                                };
                                let tagcase_ = name_regions(v, s, latent, regions);
                                match *tagcase_ {
                                    Res::Res(u, named, s) => {
                                        res(r, effs_union(close_effs(s, named), effs_union(more, effs_union(es0, es1))), lift_noted(v, noted_call(v, s, named), r, expected))
                                    }
                                }
                            }
                        }
                    }
                }
                _ => {
                    let other = tagcase_;
                    match refuse(v, string_append(str_lit("a call of a "), string_append(show_ty(s, t), str_lit(", no procedure")))) {}
                }
            }
        }
    }
}

/// A lambda of effect `es`: one that may abort returns a `Result`, and
/// one that may suspend is a future besides (C45).
pub fn noted_lambda(v: &'static Cv, s: &'static St, es: Strings) -> &'static St {
    let s = if escapes_p(es) {
        note_fact(s, cv_file(v), cv_pos(v), str_lit("fallible"))
    } else {
        s
    };
    if suspends_p(es) {
        note_fact(s, cv_file(v), cv_pos(v), str_lit("suspends"))
    } else {
        s
    }
}

/// A call of latent effect `es`: `?` after one that may abort, and
/// `.await` before it after one that may suspend (C45).
pub fn noted_call(v: &'static Cv, s: &'static St, es: Strings) -> &'static St {
    let s = if escapes_p(es) {
        note_fact(s, cv_file(v), cv_pos(v), str_lit("fallible-call"))
    } else {
        s
    };
    if suspends_p(es) {
        note_fact(s, cv_file(v), cv_pos(v), str_lit("suspending-call"))
    } else {
        s
    }
}

/// A call whose value is a procedure that cannot abort, where one that
/// may is expected: lifted, as `check-by-synth` lifts one (C35).
pub fn lift_noted(v: &'static Cv, s: &'static St, r: &'static Ty, expected: Tys) -> &'static St {
    if null_p(expected) {
        s
    } else {
        let tagcase_ = walk(s, r);
        match *tagcase_ {
            Ty::TyProc(pes, ps, r2) => {
                let tagcase_ = walk(s, car(expected));
                match *tagcase_ {
                    Ty::TyProc(ees, eps, er) => {
                        if (suspends_p(ees) && not(suspends_p(pes))) {
                            note_fact(s, cv_file(v), cv_pos(v), string_append(if escapes_p(pes) {
                                str_lit("lift-suspend-fallible ")
                            } else {
                                str_lit("lift-suspend ")
                            }, i64_to_string(size(ps))))
                        } else if (escapes_p(ees) && not(escapes_p(pes))) {
                            note_fact(s, cv_file(v), cv_pos(v), string_append(str_lit("lift "), i64_to_string(size(ps))))
                        } else {
                            s
                        }
                    }
                    _ => {
                        let other = tagcase_;
                        s
                    }
                }
            }
            _ => {
                let other = tagcase_;
                s
            }
        }
    }
}

/// The arguments, in order, but for `nil` given for a parameter that is
/// an inference variable, which is heard after the rest, as FX-26 hears
/// it. A literal is not: FX-26 makes it an `int` where it stands.
pub fn call_args(v: &'static Cv, s: &'static St, args: Sexps, ps: Tys, fixed: I64s) -> &'static Res {
    let tagcase_ = call_args_pass(v, s, args, ps, false, fixed);
    match *tagcase_ {
        Res::Res(u, es, s) => {
            with_effs(call_args_pass(v, s, args, ps, true, fixed), es)
        }
    }
}

/// A module given for a module parameter: one defined at the top level, by
/// its name, read as a global is.
pub fn module_argument(v: &'static Cv, s: &'static St, arg: &'static Sexp, t: &'static Ty) -> &'static Res {
    let name = {
        let tagcase_ = arg;
        match *tagcase_ {
            Sexp::Sym(n, at_file, at_pos) => {
                n
            }
            _ => {
                let other = tagcase_;
                str_lit("")
            }
        }
    };
    if (string_eq_p(name, str_lit("")) || null_p(find_bind(name, cv_binds(v))) || not({
        let tagcase_ = car(find_bind(name, cv_binds(v)));
        match *tagcase_ {
            Bind::Bind(n, sc, wher) => {
                string_eq_p(wher, str_lit("module"))
            }
        }
    })) {
        match refuse(v, str_lit("KFX's module argument is a module defined at the top level, by its name")) {}
    } else {
        res(t, kayak_rt::heap_cons(string_append(str_lit("g:"), name), kayak_rt::nil()), conforms(v, s, name, {
            let tagcase_ = t;
            match *tagcase_ {
                Ty::TyData(d, args) => {
                    after_prefix(d, str_lit("%module "))
                }
                _ => {
                    let other = tagcase_;
                    str_lit("")
                }
            }
        }, car(module_spec(v, t))))
    }
}

/// The arguments `deferred?` says are `later`'s.
pub fn call_args_pass(mut v: &'static Cv, mut s: &'static St, mut args: Sexps, mut ps: Tys, mut later: bool, mut fixed: I64s) -> &'static Res {
    loop {
        if null_p(args) {
            return res(ty_unit(), nil::<Str>(), s);
        } else if eqv_bool_p(deferred_p(car(args), car(ps)), later) {
            let tagcase_ = if not(null_p(module_spec(v, walk(s, car(ps))))) {
                module_argument(v, s, car(args), walk(s, car(ps)))
            } else if (not(lambda_form_p(car(args))) && has_open_p(s, car(ps))) {
                // An argument for a parameter whose type is not known whole yet:
                // found by itself, as FX-26 finds it (a literal an `int`, a
                // control form's branches of one type, a `list` at a fresh
                // region); a lambda, told its parameters, is checked.
                check_by_synth(v, s, car(args), car(ps))
            } else {
                check(v, s, car(args), car(ps))
            };
            match *tagcase_ {
                Res::Res(t, es, s) => {
                    return with_effs(call_args_pass(v, s, cdr(args), cdr(ps), later, fixed), es);
                }
            }
        } else {
            (args, ps) = (cdr(args), cdr(ps));
            continue;
        }
    }
}

